%dw 2.0
output application/json
var a = [
 	{
 		name :"Gaya3",
 		id:123,
 		Maths:90,
 	    physics :80

 	},

 	{
 		name :"devi",
 		id:456,
 		Maths :70,
 		physics:89 		
 	},
 	{
 		name :"Ravi",
 		id:789,
 		Maths:20,
 		physics:30

 	}
 ]
 fun checkResult(marks)=if(marks>50)"PASS" else "FAIL"
 ---
 a map{
 	"name" :$.name,
    "id":$.id,
 	"subjectWiseDetails":{
 		Maths:{marks:$.Maths, status:checkResult($.Maths)},
 		physics:{marks:$.physics, status:checkResult($.physics)}
 	}
 }

